/* Serial-only fixture shell for the ELF runtime: spawns tests/elf_program.c
 * with each check in turn on the real kernel, scheduler and loader, and
 * verifies exit statuses, desktop progress while user threads run, and that
 * every frame and heap object comes back. Linked in place of the desktop. */
#include "kernel/kernel.h"
#include "kernel/shell.h"
#include "kernel/platform.h"
#include "kernel/physmem.h"
#include "kernel/kheap.h"
#include "kernel/uproc.h"
#include "kernel/fs.h"
/* elf_steps.h (generated by the test) embeds the programs and defines
 * steps[]: image, size, argv[1], expected exit status and expected output. */
typedef struct {
    const unsigned char *image;   /* 0: read path from the mounted volume */
    unsigned size;
    const char *path;
    const char *check;
    int status;
    const char *output;
} ElfStep;
#include "elf_steps.h"
#define STEPS (sizeof steps / sizeof steps[0])

static unsigned step, turns, started_turns;
static uint32_t pid, began;
static PhysmemStats baseline;
static KheapStats heap_baseline;
static char output[512];
static unsigned output_length;

static void say_number(const char *label, unsigned value) {
    char text[12];
    int i = 11;
    text[i] = 0;
    do { text[--i] = (char)('0' + value % 10); value /= 10; } while (value);
    platform_log(label);
    platform_log(text + i);
    platform_log("\n");
}

static int contains(const char *text, const char *part) {
    for (; *text; ++text) {
        unsigned i = 0;
        while (part[i] && text[i] == part[i]) ++i;
        if (!part[i]) return 1;
    }
    return 0;
}

static void fail(const char *why) {
    platform_log("ELF-RUNTIME-FAIL: ");
    platform_log(why);
    platform_log("\n");
    for (;;) __asm__ volatile("cli; hlt");
}

/* Starts the current step. A negative expected status means the loader
 * must refuse the image with that error; such steps finish at once. */
static void spawn(void) {
    for (; step < STEPS; ++step) {
        const char *argv[] = {"/Programs/elf-check", steps[step].check, "last-argument"};
        output_length = 0;
        const void *image = steps[step].image;
        unsigned size = steps[step].size;
        if (!image) {
            int file = fs_resolve(fs_root(), steps[step].path);
            if (!fs_valid(file) || fs_is_dir(file)) fail("program file");
            image = fs_data(file);
            size = (unsigned)fs_size(file);
        }
        int result = uproc_spawn(image, size, argv, 3, 1, &pid);
        if (steps[step].status < 0) {
            if (result != steps[step].status) fail(steps[step].check);
            say_number("ELF refused ", (unsigned)-result);
            continue;
        }
        if (result) fail("spawn");
        started_turns = turns;
        began = timer_ticks();
        return;
    }
}

static void prepare(void) {}

static void start(void) {
    if (physmem_stats_all(&baseline) != PHYS_OK) fail("stats");
    kheap_stats(&heap_baseline);
    say_number("ELF managed pages ", baseline.total);
    spawn();
}

static int turn(void) {
    ++turns;
    if (step >= STEPS) return 0;
    output_length += uproc_take_output(pid, output + output_length, sizeof output - 1 - output_length);
    int status;
    int state = uproc_status(pid, &status);
    if (state == UPROC_RUNNING) {
        if (timer_ticks() - began > 60 * TIMER_HZ) fail("timeout");
        return 0;
    }
    if (state != UPROC_EXITED) fail("lost process");
    output_length += uproc_take_output(pid, output + output_length, sizeof output - 1 - output_length);
    output[output_length] = 0;
    platform_log(output);
    say_number("ELF exit ", (unsigned)status);
    if (status != steps[step].status) fail(steps[step].check);
    if (steps[step].output && !contains(output, steps[step].output)) fail("output");
    /* The spinning thread must not starve the desktop loop. */
    if (!kstrcmp(steps[step].check, "threads")) {
        say_number("ELF desktop turns during threads ", turns - started_turns);
        if (turns - started_turns < 5) fail("desktop starved");
    }
    if (uproc_release(pid)) fail("release");
    ++step;
    spawn();
    return 1;
}

/* Called once every process is reaped; the kernel loop frees threads. */
static int settle(void) {
    if (step < STEPS || uproc_next(0, 0)) return 0;
    PhysmemStats now;
    KheapStats heap;
    physmem_stats_all(&now);
    kheap_stats(&heap);
    /* Heap pages may stay cached; process frames and tables must not. */
    if (now.by_kind[PHYS_PROCESS_PAGE] != baseline.by_kind[PHYS_PROCESS_PAGE] ||
        now.by_kind[PHYS_PROCESS_TABLE] != baseline.by_kind[PHYS_PROCESS_TABLE])
        return 0;
    if (heap.live_objects != heap_baseline.live_objects) fail("heap objects leaked");
    platform_log("ELF-RUNTIME-PASS\n");
    step = STEPS + 1;
    return 1;
}

static int guest_turn(void) {
    int busy = turn();
    if (step == STEPS) settle();
    return busy;
}

const Shell baseos_shell = {"elf-guest", prepare, start, guest_turn};
